def parse_duration(text: str) -> int | None:
    if not isinstance(text, str) or not text:
        return None

    # Match optional hours, minutes, seconds in strict order
    match = re.fullmatch(r'(\d+h)?(\d+m)?(\d+s)?', text)
    if match:
        h_str, m_str, s_str = match.groups()
        # If all groups are None, the regex matched an empty string
        if not h_str and not m_str and not s_str:
            return None

        total = 0
        if h_str:
            total += int(h_str[:-1]) * 3600
        if m_str:
            total += int(m_str[:-1]) * 60
        if s_str:
            total += int(s_str[:-1])
        return total

    # Fallback: a plain string of digits represents seconds
    if text.isdigit():
        return int(text)

    return None
